function mix(a, b, amount) {
	const A = parseHex(a);
	const B = parseHex(b);
	if (!A || !B) return a;
	return "#" + A.map((v, i) => Math.round((v + (B[i] - v) * amount) * 255).toString(16).padStart(2, "0")).join("");
}

